entries[23486] = { ["name"] = "Dimensionszerfetzer: Ewige Warte", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilbarren (10), Echtsilberumwandler , Herz des Feuers (4), Sternrubin (2), Der Große\nDimensionszerfetzer: Ewige Warte\nWird bei Benutzung gebunden\nSpielzeug\nBenötigt Ingenieurskunst\n(260)\nBenötigt Gobliningenieur\nBenutzen: Reißt die dimensionalen Mauern ein, um Euch zur Ewigen Warte in Winterquell zu transportieren. Es gibt da zwar einige technische Probleme, die manchmal auftreten, aber das muss man halt bei dem Ingenieurswesen der Goblins mit einkalkulieren! (4 Std. Abklingzeit)" }
