entries[24654] = { ["name"] = "Blaue Drachenschuppengamaschen", ["text"] = "Wirken in 45 sek.\nReagenzien:\nUnverwüstliches Leder (28), Blaue Drachenschuppe (36), Geschmeidiger unverwüstlicher Balg (2), Runenfaden (2)\nBlaue Drachenschuppengamaschen\nWird beim Anlegen gebunden\nBeine Kette\n310 Rüstung\n+23 Intelligenz\nHaltbarkeit 90 / 90\n55\nAnlegen: Stellt alle 5 Sek. 8 Mana wieder her.\nAnlegen: Erhöht die Zaubermacht um 17.\n\nBlauer Drachenschuppenpanzer (0/3)\nBlaue Drachenschuppenbrustplatte\nBlaue Drachenschuppengamaschen\nBlaue Drachenschuppenschultern" }
entries[24655] = { ["name"] = "Grüne Drachenschuppenstulpen", ["text"] = "Wirken in 45 sek.\nReagenzien:\nUnverwüstliches Leder (20), Grüne Drachenschuppe (30), Geschmeidiger unverwüstlicher Balg , Runenfaden (2)\nGrüne Drachenschuppenstulpen\nWird beim Anlegen gebunden\nHände Kette\n201 Rüstung\n+7 Ausdauer\n+10 Intelligenz\n+9 Naturwiderstand\nHaltbarkeit 40 / 40\n49\nAnlegen: Erhöht die Zaubermacht um 21.\n\nGrüner Drachenschuppenpanzer (0/3)\nGrüne Drachenschuppenbrustplatte\nGrüne Drachenschuppengamaschen\nGrüne Drachenschuppenstulpen" }
entries[24658] = { ["name"] = "Instabile Macht", ["text"] = "Sofort\nErhöht 20 sec lang Eure Zaubermacht um 204. Bei jedem Wirken eines Zaubers wird der Bonus um 17 Zaubermacht reduziert." }
