entries[24669] = { ["name"] = "Feuerregen", ["text"] = "250 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nLässt einen Schmelzregen niedergehen, der alle Feinde im ausgewählten Gebiet verbrennt und ihnen 10 sec lang alle 2 Sek. 500 Feuerschaden zufügt." }
entries[24670] = { ["name"] = "Inferno", ["text"] = "350 Mana 100 Meter Reichweite\nWirken in 3 sek.\nReagenzien:\nHöllenstein\nBeschwört einen Meteor aus dem Wirbelnden Nether, der 200 Punkt(e) Feuerschaden verursacht und alle feindlichen Ziele in dem Gebiet 2 sec lang betäubt. Aus dem Krater erhebt sich eine Höllenbestie, die 1 min lang unter dem Befehl des Zaubernden steht. Sobald die Kontrolle verloren ist, muss die Höllenbestie unterworfen werden, um sie unter Kontrolle zu halten. Kann nur draußen verwendet werden." }
